// Two-wheel line follower: an eight-sensor QTR-8RC array, a TB6612FNG driver, proportional steering.
#include <QTRSensors.h>

QTRSensors qtr;
const uint8_t SENSORS[8] = {A0, A1, A2, A3, A4, A5, 11, 12};   // left to right
uint16_t values[8];

const int PWMA = 5, AIN1 = 7, AIN2 = 8;      // left motor
const int PWMB = 6, BIN1 = 10, BIN2 = 4;     // right motor
const int STBY = 9, EMITTER = 2, LOOP_PIN = 13;

const int BASE = 140;                // out of 255; the pack is 7.4 V and the motors are 6 V
const int DARK_FLOOR = 500;          // microseconds; white reads about 120, the line reads 2500
const float DEG_PER_S_PER_COUNT = 1.2;   // turn rate for each count of left-right difference (iynk estimate)

int lastPos = 3500;
float heading = 0;
int laps = 0;
unsigned long lastUs;

int linePosition() {
  qtr.read(values);
  long weighted = 0, total = 0;
  for (int i = 0; i < 8; i++) {
    long dark = values[i] > DARK_FLOOR ? values[i] : 0;
    weighted += dark * i * 1000L;
    total += dark;
  }
  if (total > 0) lastPos = weighted / total;   // 0 (line far left) to 7000 (far right)
  return lastPos;
}

void wheel(int in1, int in2, int pwm, int speed) {
  digitalWrite(in1, speed >= 0 ? HIGH : LOW);
  digitalWrite(in2, speed >= 0 ? LOW : HIGH);
  analogWrite(pwm, constrain(abs(speed), 0, 255));
}

void drive(int left, int right) {
  wheel(AIN1, AIN2, PWMA, left);
  wheel(BIN1, BIN2, PWMB, right);
}

// The track runs anticlockwise, so one lap is 360 degrees of turning left.
void countLaps(int left, int right) {
  unsigned long now = micros();
  heading += (constrain(right, 0, 255) - constrain(left, 0, 255)) * DEG_PER_S_PER_COUNT * (now - lastUs) * 0.000001;
  lastUs = now;
  if (heading >= 360) {
    heading -= 360;
    laps++;
    Serial.print("lap ");
    Serial.println(laps);
  }
}

void setup() {
  Serial.begin(9600);
  qtr.setTypeRC();
  qtr.setSensorPins(SENSORS, 8);
  qtr.setEmitterPin(EMITTER);
  for (int p = 4; p <= 10; p++) pinMode(p, OUTPUT);
  pinMode(LOOP_PIN, OUTPUT);
  digitalWrite(STBY, HIGH);
  lastUs = micros();
  Serial.println("follow: Kp 0.05, base 140");
}

void loop() {
  static bool beat = false;
  beat = !beat;
  digitalWrite(LOOP_PIN, beat);

  int error = linePosition() - 3500;
  int turn = error / 20;
  drive(BASE + turn, BASE - turn);
  countLaps(BASE + turn, BASE - turn);
  delay(7);
}
